    id: "eng-2023-hl-q2-a-i", topicId: "eng-3-14", conceptId: "term-extended-reality-xr",
    section: "A", questionRef: "2023 HL Q2(a)(i)",
    questionText: "Describe the term Extended Reality (XR).",
    tariffModel: {"kind":"fixed"}, totalMarks: 5,
