    id: "eng-2023-hl-q3-c-i", topicId: "eng-3-8", conceptId: "aid-suitable-diagrams-ultrasonic-non-destructive",
    section: "A", questionRef: "2023 HL Q3(c)(i)",
    questionText: "Describe, with the aid of suitable diagrams, ultrasonic non-destructive testing.",
    tariffModel: {"kind":"fixed"}, totalMarks: 8,
    rows: [
    { id: "r-1", kind: "point", verbatim: "A quartz crystal is used to generate high frequency vibrations and passed over the material to be tested. If the material has internal defects, vibrations will be reflected quicker back to the receiver and displayed on a screen. It is used to test thick components such as castings and forgings for defects. It is quick and has the ability to probe deeply without damaging the piece. Ultrasonic wave generation and use is safe for humans, therefore no extra safety precautions need to be taken.", marks: 8 },
    ],
